<script setup lang="ts">import {computed,ref} from 'vue';import AppShell from '@/components/zs/AppShell.vue';import PageHeader from '@/components/zs/PageHeader.vue';import Panel from '@/components/zs/Panel.vue';import StatCard from '@/components/zs/StatCard.vue';import DataTable from '@/components/zs/DataTable.vue';import StatusBadge from '@/components/zs/StatusBadge.vue';import SidePanel from '@/components/zs/SidePanel.vue';import AIInsightCard from '@/components/crm/AIInsightCard.vue';import {useCrmData} from '@/composables/useCrmData';import type {EmailEvent} from '@/types/crm';import {setPageMeta} from '@/lib/page-meta';setPageMeta('Email Tracking','Outreach delivery and reply timeline.');const d=useCrmData(),selected=ref<EmailEvent|null>(null),rows=computed(()=>d.emails.data.value??[]);const columns=[{key:'date',header:'Date / time'},{key:'subject',header:'Subject'},{key:'sequence',header:'Sequence'},{key:'status',header:'Status'},{key:'sender',header:'Sender'},{key:'step',header:'Step',align:'right' as const}];</script>
<template><AppShell><PageHeader title="Email Tracking" description="Mock delivery events prepared for the future tracking service"/><div class="mb-3 grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><StatCard label="Sent" :value="String(rows.length)"/><StatCard label="Delivered" :value="String(rows.filter(x=>x.status!=='Sent').length)" tone="success"/><StatCard label="Opened" :value="String(rows.filter(x=>['Opened','Replied'].includes(x.status)).length)" tone="brand"/><StatCard label="Replied" :value="String(rows.filter(x=>x.status==='Replied').length)" tone="warning"/><StatCard label="Reply rate" :value="`${rows.length?Math.round(rows.filter(x=>x.status==='Replied').length/rows.length*100):0}%`"/></div><Panel><DataTable :columns="columns" :rows="rows" :min-width="900"><template #subject="{row}"><button class="font-medium text-primary hover:underline" @click="selected=row">{{row.subject}}</button></template><template #status="{row}"><StatusBadge :status="row.status"/></template><template #step="{row}"><span class="num">{{row.step}}</span></template></DataTable></Panel><SidePanel :open="!!selected" title="Email content" :description="selected?.subject" @close="selected=null"><template v-if="selected"><div class="flex items-center justify-between"><StatusBadge :status="selected.status"/><span class="num text-2xs text-content-muted">Step {{selected.step}}</span></div><pre class="mt-5 whitespace-pre-wrap font-sans text-sm leading-6 text-content-secondary">{{selected.body}}</pre><AIInsightCard class="mt-5" title="Conversation summary" content="Lead showed interest in pricing and requested more information about implementation."/></template></SidePanel></AppShell></template>
